{
  "part": {
    "name": "Tapered clevis-to-hook lever",
    "description": "Single-piece elongated lever with a tapered load-carrying arm, a two-cheek clevis and transverse pin interface at one end, and an open J-shaped capture hook at the opposite end.",
    "source_views": [
      "front",
      "back",
      "left",
      "right",
      "top",
      "bottom",
      "toprightiso"
    ],
    "symmetry_note": "The part is substantially mirror-symmetric about the longitudinal x-z center plane at y=0. The positive-y and negative-y clevis cheeks, transverse bore portions, and long side surfaces form mirrored pairs. The part is not symmetric through its thickness because the upper and lower arm profiles and terminal hook geometry differ."
  },
  "Section": [
    {
      "id": "S01",
      "name": "Tapered load arm",
      "features included": [
        "longitudinal structural spine",
        "tapered beam",
        "broad upper and lower facets",
        "paired longitudinal side facets",
        "load path between clevis and hook"
      ],
      "function intent": "Provides reach between the two end interfaces and transmits tensile, bending, shear, and torsional loads from the clevis connection to the hook.",
      "physical behavior": "The arm behaves primarily as a tapered beam. Its greater depth and width near the clevis increase stiffness and reduce connection stress, while the reduced section toward the hook lowers mass. The four broad exterior facets form a closed solid section that resists bending in both principal directions and provides some torsional rigidity.",
      "geometry": "Long, solid, slightly tapered prismatic body extending along the x direction. It is bounded by two broad inclined planar surfaces in z and two broad side planes in y. The STEP faces continue uninterrupted into portions of the end transitions, but their dominant geometric and functional extent belongs to the arm.",
      "location": "Central portion of the part, between the negative-x clevis and positive-x hook.",
      "colour": {
        "R": 70,
        "G": 130,
        "B": 180
      },
      "major_faces": [
        {
          "face_code": "0000",
          "name": "Upper arm facet",
          "Brep_id": "FACE 5",
          "description": "Large inclined planar surface forming the upper longitudinal boundary of the tapered arm."
        },
        {
          "face_code": "0001",
          "name": "Negative-y arm side",
          "Brep_id": "FACE 9",
          "description": "Large longitudinal side plane on the negative-y side, extending through the arm and portions of both end features."
        },
        {
          "face_code": "0002",
          "name": "Lower arm facet",
          "Brep_id": "FACE 11",
          "description": "Large inclined planar surface forming the lower longitudinal boundary of the tapered arm."
        },
        {
          "face_code": "0003",
          "name": "Positive-y arm side",
          "Brep_id": "FACE 16",
          "description": "Large longitudinal side plane on the positive-y side, mirrored to FACE 9 and extending through portions of the end features."
        }
      ],
      "minor_faces_Brep_id": [],
      "relationships": [
        {
          "source id": "S01",
          "target id": "S02",
          "function relationship": "transmits_load, distributes_stress",
          "structural relationship": "attached_to, blends_into, supports"
        },
        {
          "source id": "S01",
          "target id": "S03",
          "function relationship": "transmits_load, distributes_stress",
          "structural relationship": "attached_to, blends_into, supports"
        },
        {
          "source id": "S01",
          "target id": "S04",
          "function relationship": "transmits_load, provides_clearance",
          "structural relationship": "attached_to, adjacent_to, supports"
        },
        {
          "source id": "S01",
          "target id": "S05",
          "function relationship": "transmits_load, distributes_stress",
          "structural relationship": "attached_to, blends_into, supports"
        }
      ]
    },
    {
      "id": "S02",
      "name": "Positive-y clevis cheek",
      "features included": [
        "clevis lug",
        "transverse pin bore portion",
        "rounded lug crown",
        "inner locating cheek",
        "pin-supported mounting point"
      ],
      "function intent": "Forms one side of the clevis, supports one end of a transverse pin, and provides a planar cheek for laterally locating a mating link inserted into the clevis slot.",
      "physical behavior": "The cheek carries pin bearing pressure around its cylindrical bore and transfers the resulting shear and bending load into the widened end of the arm. The rounded crown maintains material around the bore and reduces stress concentration compared with a square-ended lug.",
      "geometry": "Positive-y fork plate at the negative-x end. It has a planar inner face at y=3.5 mm, a cylindrical bore of 3 mm radius aligned with the y axis, and a 7.5 mm radius rounded exterior crown around the pin region.",
      "location": "Negative-x end of the part, offset toward positive y.",
      "colour": {
        "R": 230,
        "G": 90,
        "B": 90
      },
      "major_faces": [
        {
          "face_code": "0004",
          "name": "Positive lug outer crown",
          "Brep_id": "FACE 15",
          "description": "Convex cylindrical exterior wrapping around the rounded negative-x end of the positive-y clevis cheek."
        },
        {
          "face_code": "0005",
          "name": "Positive lug inner cheek",
          "Brep_id": "FACE 4",
          "description": "Planar y=3.5 mm face bordering the clevis slot and containing the inner opening of the transverse pin bore."
        },
        {
          "face_code": "0006",
          "name": "Positive lug bore wall",
          "Brep_id": "FACE 0",
          "description": "Cylindrical 3 mm radius pin-bearing surface through the positive-y clevis cheek, coaxial with the negative-y bore portion."
        }
      ],
      "minor_faces_Brep_id": [],
      "relationships": [
        {
          "source id": "S02",
          "target id": "S03",
          "function relationship": "locates_mating_part, constrains_dof",
          "structural relationship": "coaxial_with, offset_from"
        },
        {
          "source id": "S02",
          "target id": "S04",
          "function relationship": "locates_mating_part, provides_clearance, distributes_stress",
          "structural relationship": "adjacent_to, attached_to"
        },
        {
          "source id": "S02",
          "target id": "S01",
          "function relationship": "transmits_load",
          "structural relationship": "attached_to, blends_into"
        }
      ]
    },
    {
      "id": "S03",
      "name": "Negative-y clevis cheek",
      "features included": [
        "clevis lug",
        "transverse pin bore portion",
        "rounded lug crown",
        "inner locating cheek",
        "pin-supported mounting point"
      ],
      "function intent": "Forms the opposing side of the clevis, supports the other end of the transverse pin, and cooperates with the positive-y cheek to constrain a mating link laterally.",
      "physical behavior": "This cheek reacts the opposite share of pin bearing and shear. Together with the positive-y cheek it limits pin tilting, distributes load over two supports, and transfers force into the broad end of the tapered arm.",
      "geometry": "Negative-y fork plate at the negative-x end, mirrored across y=0 from S02. It includes a planar inner slot face at y=-3.5 mm, a 3 mm radius y-axis bore, and a 7.5 mm radius exterior crown.",
      "location": "Negative-x end of the part, offset toward negative y.",
      "colour": {
        "R": 245,
        "G": 165,
        "B": 65
      },
      "major_faces": [
        {
          "face_code": "0007",
          "name": "Negative lug bore wall",
          "Brep_id": "FACE 1",
          "description": "Cylindrical 3 mm radius pin-bearing surface through the negative-y clevis cheek."
        },
        {
          "face_code": "0008",
          "name": "Negative lug inner cheek",
          "Brep_id": "FACE 3",
          "description": "Planar y=-3.5 mm face bordering the clevis slot and containing the inner opening of the transverse pin bore."
        },
        {
          "face_code": "0009",
          "name": "Negative lug outer crown",
          "Brep_id": "FACE 6",
          "description": "Convex cylindrical exterior wrapping around the rounded negative-x end of the negative-y clevis cheek."
        }
      ],
      "minor_faces_Brep_id": [],
      "relationships": [
        {
          "source id": "S03",
          "target id": "S02",
          "function relationship": "locates_mating_part, constrains_dof",
          "structural relationship": "coaxial_with, offset_from"
        },
        {
          "source id": "S03",
          "target id": "S04",
          "function relationship": "locates_mating_part, provides_clearance, distributes_stress",
          "structural relationship": "adjacent_to, attached_to"
        },
        {
          "source id": "S03",
          "target id": "S01",
          "function relationship": "transmits_load",
          "structural relationship": "attached_to, blends_into"
        }
      ]
    },
    {
      "id": "S04",
      "name": "Clevis slot termination",
      "features included": [
        "central clevis cavity",
        "mating-link clearance slot",
        "slot end wall",
        "cheek-spacing bridge"
      ],
      "function intent": "Provides clearance for a mating eye or link between the two clevis cheeks and establishes the insertion limit at the closed end of the slot.",
      "physical behavior": "The open slot allows the mating member to enter without interference. The closed planar end wall ties the cheek roots into the arm, maintains their spacing, and can react incidental contact if the mating link reaches the bottom of the slot.",
      "geometry": "Central open-ended rectangular clevis slot between y=-3.5 mm and y=3.5 mm. Its visually distinct closed end is a plane normal to the x axis at x=-60.75 mm; the slot opens toward the rounded negative-x end.",
      "location": "Centered at y=0 within the negative-x clevis, between S02 and S03 and immediately ahead of the tapered arm.",
      "colour": {
        "R": 150,
        "G": 105,
        "B": 200
      },
      "major_faces": [
        {
          "face_code": "0010",
          "name": "Clevis slot end wall",
          "Brep_id": "FACE 2",
          "description": "Planar transverse wall closing the inner end of the clevis cavity and joining the slot region to the arm."
        }
      ],
      "minor_faces_Brep_id": [],
      "relationships": [
        {
          "source id": "S04",
          "target id": "S02",
          "function relationship": "provides_clearance, locates_mating_part",
          "structural relationship": "adjacent_to, attached_to, supports"
        },
        {
          "source id": "S04",
          "target id": "S03",
          "function relationship": "provides_clearance, locates_mating_part",
          "structural relationship": "adjacent_to, attached_to, supports"
        },
        {
          "source id": "S04",
          "target id": "S01",
          "function relationship": "transmits_load, distributes_stress",
          "structural relationship": "attached_to, blends_into"
        }
      ]
    },
    {
      "id": "S05",
      "name": "Terminal capture hook",
      "features included": [
        "open J-shaped hook",
        "concave capture throat",
        "convex load-bearing heel",
        "upright terminal post",
        "rounded post exterior",
        "top cap",
        "retention opening"
      ],
      "function intent": "Engages and retains a rod, pin, cable, or edge without requiring a separate fastener, while permitting installation or removal through the open throat.",
      "physical behavior": "A captured member bears against the concave throat and lower hook seat. The thick convex heel carries the resulting contact force into the tapered arm. The upright terminal post obstructs direct withdrawal and increases the motion required for disengagement. Curved surfaces spread contact and reduce local stress concentration.",
      "geometry": "Positive-x end shaped as an open J hook in the x-z plane. The hook contains a 3 mm radius concave cylindrical throat, a larger 9 mm radius convex lower heel, a short upper curved transition, and a rounded vertical terminal post with a 3 mm radius cylindrical exterior and planar top cap.",
      "location": "Positive-x tip of the part, opposite the clevis.",
      "colour": {
        "R": 70,
        "G": 180,
        "B": 110
      },
      "major_faces": [
        {
          "face_code": "0011",
          "name": "Hook throat",
          "Brep_id": "FACE 7",
          "description": "Concave 3 mm radius cylindrical surface forming the inner capture seat and throat of the hook."
        },
        {
          "face_code": "0012",
          "name": "Upper throat transition",
          "Brep_id": "FACE 8",
          "description": "Short 3 mm radius cylindrical transition connecting the concave throat region toward the top of the terminal post."
        },
        {
          "face_code": "0013",
          "name": "Terminal top cap",
          "Brep_id": "FACE 17",
          "description": "Planar horizontal face at z=15 mm closing the top of the upright terminal feature."
        },
        {
          "face_code": "0014",
          "name": "Terminal post exterior",
          "Brep_id": "FACE 13",
          "description": "Convex 3 mm radius cylindrical surface about the z axis forming the rounded outside of the upright hook tip."
        },
        {
          "face_code": "0015",
          "name": "Hook outer heel",
          "Brep_id": "FACE 10",
          "description": "Large convex 9 mm radius cylindrical surface forming the lower load-bearing heel and outer return of the hook."
        }
      ],
      "minor_faces_Brep_id": [
        "FACE 12",
        "FACE 14"
      ],
      "relationships": [
        {
          "source id": "S05",
          "target id": "S01",
          "function relationship": "transmits_load, distributes_stress",
          "structural relationship": "attached_to, blends_into, supported_by"
        }
      ]
    }
  ]
}
